/// The gallery's example of `DateTimePicker`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_label = args.text("label");
        let arg_disabled = args.bool("disabled");
        let arg_read_only = args.bool("read_only");
        let arg_step_minutes = args.number("step_minutes") as u16;

        let month = Date::new(2026, 11, 1).unwrap_or_else(|| Date::from_days(0));
        let at = State::new(Time::new(14, 0).map(|time| DateTime { date: month, time }));
        {
            let mut it = DateTimePicker::new(at.binding(), month);
            it = it.label(arg_label.clone());
            it = it.disabled(arg_disabled);
            it = it.read_only(arg_read_only);
            it = it.step_minutes(arg_step_minutes);
            it
        }
    })
}

